    const amountLabel=document.createElement('label');amountLabel.textContent=t('Montant total à reporter (F CFA)','Total amount to fill (CFA francs)');const amount=document.createElement('input');amount.type='number';amount.min='0';amount.step='1';amount.inputMode='numeric';amountLabel.append(amount);
    const status=document.createElement('p');status.setAttribute('role','status');
    const reading=document.createElement('output');reading.className='eco-voice-amount-reading';reading.setAttribute('aria-live','polite');
    const acknowledgement=document.createElement('label'),ack=document.createElement('input');ack.type='checkbox';acknowledgement.append(ack,document.createTextNode(t('J’ai vérifié le montant entendu et le montant en lettres.','I checked the heard amount and the amount in words.')));acknowledgement.hidden=true;
    const alternatives=document.createElement('div');alternatives.className='eco-voice-alternatives';
    const engineLabel=document.createElement('label');engineLabel.textContent=t('Moteur de dictée','Dictation engine');const engine=document.createElement('select');for(const [value,fr,en]of [['browser','Navigateur · Internet possible','Browser · may use Internet'],['local','Langue locale du navigateur · si compatible','Browser language pack · if supported'],['vosk','Vosk français · modèle libre facultatif','French Vosk · optional open-source model']]){const o=document.createElement('option');o.value=value;o.textContent=t(fr,en);engine.append(o);}engineLabel.append(engine);
    const install=document.createElement('button');install.type='button';install.className='secondary';install.textContent=t('Installer la langue pour la dictée locale','Install language for on-device dictation');install.hidden=true;
    const installModel=document.createElement('button'),deleteModel=document.createElement('button');for(const b of[installModel,deleteModel]){b.type='button';b.className='secondary';b.hidden=true;}
    installModel.textContent=t('Télécharger Vosk français · environ 48 Mo, puis extraction locale','Download French Vosk · about 48 MB, then local extraction');deleteModel.textContent=t('Retirer uniquement le modèle vocal Eco','Remove only the Eco voice model');
    const modelNotice=document.createElement('p');modelNotice.className='hint';modelNotice.hidden=true;modelNotice.textContent=t('Facultatif. Le son reste sur cet appareil. Le premier chargement demande du temps et de la mémoire. La performance en réunion et sur votre téléphone doit être testée. Aucun modèle ne valide un montant à votre place.','Optional. Audio stays on this device. First loading takes time and memory. Meeting and phone performance must be tested. No model confirms an amount for you.');
    const checkModel=async()=>{const installed=await localModelInstalled();if(closed||engine.value!=='vosk')return;installModel.hidden=installed;deleteModel.hidden=!installed;listen.disabled=!installed;status.textContent=installed?t('Modèle français présent · utilisable hors ligne après chargement.','French model installed · available offline after loading.'):t('Téléchargement volontaire requis. Choisissez une connexion adaptée ; le clavier reste disponible.','Optional download required. Choose a suitable connection; the keyboard remains available.');};
    installModel.onclick=()=>void(async()=>{installModel.disabled=true;try{await installLocalModel(value=>{if(!closed)status.textContent=t('Téléchargement du modèle : ','Model download: ')+value;});await checkModel();}catch(error){if(!closed)status.textContent=t('Installation incomplète, reprise possible : ','Installation incomplete, resume available: ')+String(error);}finally{installModel.disabled=false;}})();
    deleteModel.onclick=()=>void(async()=>{controller?.stop();deleteModel.disabled=true;try{await removeLocalModel();await checkModel();if(!closed)status.textContent=t('Modèle vocal Eco retiré. Les données métier et opérations en attente sont conservées.','Eco voice model removed. Business data and pending operations are preserved.');}catch(error){if(!closed)status.textContent=String(error);}finally{deleteModel.disabled=false;}})();
    let confidence:number|undefined,uncertain=false;
    engine.onchange=()=>void(async()=>{controller?.stop();modelNotice.hidden=engine.value!=='vosk';installModel.hidden=deleteModel.hidden=true;if(engine.value==='vosk'){install.hidden=true;await checkModel();return;}if(engine.value!=='local'){install.hidden=true;listen.disabled=false;return;}const available=await localVoiceAvailability(uiEn()?'en-US':'fr-FR');if(closed)return;install.hidden=available!=='downloadable'&&available!=='downloading';listen.disabled=available!=='available';status.textContent=available==='available'?t('Langue installée · le son reste sur cet appareil.','Language installed · audio stays on this device.'):available==='unsupported'||available==='unavailable'?t('La dictée locale n’est pas disponible sur ce navigateur. Le clavier et la dictée du navigateur restent accessibles.','On-device dictation is unavailable in this browser. Keyboard and browser dictation remain available.'):t('Téléchargement de langue requis. Lancez l’installation uniquement sur le réseau de votre choix.','A language download is required. Start installation on a network of your choice.');})();
